wyj_voids=Class(background)function wyj_voids:init()	--	background.init(self,false)	--resource	--set 3d camera and fog	Set3D('eye',0,0.0,0.3)	Set3D('at',0,0,-4.8)	Set3D('up',0,1,0)	Set3D('fovy',2)	Set3D('z',0.1,500)	Set3D('fog',0,0,Color(1,50,50,255))	--	--New(camera_setter)endfunction wyj_voids:frame()endfunction wyj_voids:render()	SetViewMode'3d'	SetViewMode'world'end